import React from "react";
import withNavigation from "../utils/withNavigation";
import axiosInstance from "../configurations/instance";

class AuthUser extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      email: "",
      password: "",
    };
  }

  handleLogin = () => {
    const { email, password } = this.state;

    axiosInstance
      .post("/auth/check-user", { email, password })
      .then((response) => {
        console.log("Авторизация успешна:", response.data);

        localStorage.setItem("token", response.data.token);

        const role = response.data.role;
        if (role === "Organisation") {
          this.props.navigate("/organisation-dashboard");
        } else if (role === "Checker") {
          this.props.navigate("/checker-dashboard");
        } else {
          console.error("Неизвестная роль:", role);
        }
      })
      .catch((error) => {
        console.error("Ошибка авторизации:", error);
        alert("Неверный логин или пароль.");
      });
  };

  handleRegisterClick = () => {
    this.props.navigate("/role-selection");
  };

  handlePasswordClick = () => {
    this.props.navigate("/forget-password");
  };

  render() {
    return (
      <div className="auth-container">
        <h2>Логин</h2>
        <div className="form-group">
          <label>Email</label>
          <input
            type="text"
            value={this.state.email}
            onChange={(e) => this.setState({ email: e.target.value })}
            placeholder="Введите почту"
          />
        </div>
        <div className="form-group1">
          <label>Пароль</label>
          <input
            type="password"
            value={this.state.password}
            onChange={(e) => this.setState({ password: e.target.value })}
            placeholder="Введите пароль"
          />
        </div>
        <button className="reg-button" onClick={this.handleLogin}>
          Войти
        </button>
        <div className="links">
          <a href="#" onClick={this.handlePasswordClick}>
            Забыли пароль?
          </a>
          <span> | </span>
          <a href="#" onClick={this.handleRegisterClick}>
            Регистрация
          </a>
        </div>
      </div>
    );
  }
}

export default withNavigation(AuthUser);
